    else if (n.kind === 'var') {
      const h = n.expr.match(/^(currency|date)\s+([\w.@]+)$/);
      if (h) out += h[1] === 'currency' ? fmtCurrency(get(h[2], scope)) : fmtDate(get(h[2], scope));
      else {
        const v = get(n.expr, scope);
        if (v === undefined || v === null) { warnings.add(`unresolved field: ${n.expr}`); }
        else if (typeof v === 'object') { warnings.add(`field is not a plain value: ${n.expr}`); }
        else out += esc(v);
      }
    } else if (n.kind === 'if') {
      const v = get(n.path, scope);
      const truthy = Array.isArray(v) ? v.length > 0 : !!v;
      out += evalNodes(truthy ? n.body : n.no, scope);
    } else if (n.kind === 'each') {
      const list = get(n.path, scope);
      if (!Array.isArray(list)) { warnings.add(`#each ${n.path} is not an array`); continue; }
      list.forEach((item, i) => { out += evalNodes(n.body, [...scope, { value: item, number: i + 1 }]); });
    }
  }
  return out;
}

let html;
try {
  html = evalNodes(parse(ctx.template_html).body, [{ value: { ...ctx.render_data, document_number: number }, number: 0 }]);
} catch (err) { return fail(String(err.message || err)); }

const binary = { data: await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html') };
return [{ json: { ...ctx, ok: true, document_number: number, warnings: [...warnings], html_bytes: Buffer.byteLength(html) }, binary }];

const ctx = $('Render Document').first().json;
const r = $input.first();
const fail = (detail) => [{ json: { ...ctx, ok: false, failure_stage: 'pdf', failure_detail: detail } }];
if (r.json.error) return fail('renderer error: ' + String(r.json.error.message || r.json.error).slice(0, 200));
if (r.json.statusCode !== 200 || !r.binary || !r.binary.data) return fail('renderer returned status ' + r.json.statusCode);
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (buf.length < 8 || buf.slice(0, 4).toString('latin1') !== '%PDF') return fail('renderer response is not a PDF');
r.binary.data.fileName = `${ctx.document_number}.pdf`;
r.binary.data.mimeType = 'application/pdf';
return [{ json: { ...ctx, ok: true, pdf_bytes: buf.length }, binary: { data: r.binary.data } }];

const ctx = $('Check PDF').first().json;
const r = $input.first().json;
const archive_url = r.body && typeof r.body === 'object' ? r.body.archive_url : null;
if (r.error || !(r.statusCode >= 200 && r.statusCode < 300) || !archive_url)
  return [{ json: { ...ctx, ok: false, failure_stage: 'archive', failure_detail: r.error ? String(r.error.message || r.error).slice(0, 200) : `archive returned status ${r.statusCode}` } }];
return [{ json: { ...ctx, ok: true, archive_url } }];

const C = $('CONFIG').first().json;
const ctx = $('Check Archive').first().json;
const r = $input.first().json;
const warnings = [...(ctx.warnings || [])];
const record_failed = !!r.error;
if (record_failed) warnings.push('record_status_update_failed: document is archived but its record is still pending; ops alerted');
const R = $('Document Rules').first().json.rules;
const send_email = !!C.SEND_EMAIL && !!(ctx.recipient && ctx.recipient.email) && !R.no_email_types.includes(ctx.document_type);   // Document Rules: some types are never emailed
return [{ json: { ...ctx, warnings, record_failed, send_email } }];

const ctx = $('Prepare Delivery').first().json;
const r = $input.first().json;
const email_failed = !!r.error || !(r.statusCode >= 200 && r.statusCode < 300);
const warnings = [...ctx.warnings];
if (email_failed) warnings.push(`delivery_email_failed: ${ctx.recipient.email}`);
return [{ json: { ...ctx, warnings, email_failed } }];

const ctx = $('Prepare Delivery').first().json;
const r = $input.first().json;
let email = 'skipped', warnings = [...ctx.warnings];
if (ctx.send_email) {
  try { const d = $('Check Delivery').first().json; email = d.email_failed ? 'failed' : 'sent'; warnings = [...d.warnings]; } catch (err) { email = 'unknown'; }
}
if (r.error) warnings.push('audit_log_failed');
return [{ json: { ok: true, http_status: 201, response_body: {
  status: 'completed', document_number: ctx.document_number, archive_url: ctx.archive_url,
  delivery: { email }, warnings } } }];

const f = $input.first().json;
const retry_hint = f.mode === 'generate' ? 'The generation record is marked failed_needs_retry. Re-send the same request with the same idempotency_key to retry; the same document number is reused.' : undefined;
const map = {
  render: { status: 500, error: 'template_render_failed' },
  pdf: { status: 502, error: 'pdf_generation_failed' },
  archive: { status: 502, error: 'archive_failed' },
};
const m = map[f.failure_stage] || { status: 500, error: 'generation_failed' };
const alert = f.failure_stage === 'archive'
  ? `:rotating_light: Document ${f.document_number} rendered but could not be archived. The caller got a 502, not a success. The record is failed_needs_retry; the same idempotency_key will retry it.`
  : null;
return [{ json: { ...f, http_status: m.status, response_body: { error: m.error, document_number: f.mode === 'generate' ? f.document_number : null, detail: f.failure_detail, ...(retry_hint ? { retry: retry_hint } : {}) }, alert_text: alert } }];
